WorkflowProcessEvent.eventDescription:
function afterProcessCreate(processId) {
	hAPI.setCardValue("hd_solicitacao_numProcesso", processId);
	// Filial, medicao e valor chegam do Protheus nos dados de abertura; o descritor sai
	// daqui ja na criacao. O inputFields do formulario remonta a cada gravacao.
	hAPI.setCardValue(
		"campo_descritor",
		montaDescritor(
			hAPI.getCardValue("hd_solicitacao_nroFilial"),
			hAPI.getCardValue("hd_medicao_numero"),
			hAPI.getCardValue("hd_contrato_valor")
		)
	);
}

/** "Filial: 01 | Medição: 002564 | Valor: R$592.42". O valor vem como "R$ 592,42" ou "592.42". */
function montaDescritor(filial, medicao, valor) {
	var texto = ((valor || "") + "").replace(/[^\d,.-]/g, "");
	if (texto.indexOf(",") >= 0) {
		texto = texto.replace(/\./g, "").replace(",", ".");
	}
	var numero = parseFloat(texto);
	return (
		"Filial: " +
		((filial || "") + "").trim() +
		" | Medição: " +
		((medicao || "") + "").trim() +
		" | Valor: R$" +
		(isNaN(numero) ? "" : numero.toFixed(2))
	);
}

function beforeTaskSave(colleagueId,nextSequenceId,userList){
	hAPI.setCardValue("hd_solicitacao_atvAtual", nextSequenceId);
    var codProcess = getValue("WKNumProces");
    var states = {
        next    : getValue("WKNextState"),
        actual  : getValue("WKNumState"),
        etapa   : ""
    }

    if(states.next == 16){
        hAPI.setCardValue("hd_aprovacao_solicitacao", formatarDataAtual(true));
    }
}

function formatarDataAtual(comHorario){
    var data = new Date();
    var dia  = data.getDate().toString(); dia = (dia.length>1)? dia : "0"+dia;
    var mes  = (data.getMonth()+1).toString(); mes = (mes.length>1)? mes : "0"+mes;
    var ano  = data.getFullYear();
    var hora = data.getHours().toString(); hora = (hora.length>1)? hora : "0"+hora;
    var minutos = data.getMinutes().toString(); minutos = (minutos.length>1)? minutos : "0"+minutos;
    if(comHorario){
        return dia+"/"+mes+"/"+ano + " " + hora+":"+minutos;
    }
    return dia+"/"+mes+"/"+ano;
}

function formatarDataEnAtual(comHorario){
    var data = new Date();
    var dia  = data.getDate().toString(); dia = (dia.length>1)? dia : "0"+dia;
    var mes  = (data.getMonth()+1).toString(); mes = (mes.length>1)? mes : "0"+mes;
    var ano  = data.getFullYear();
    var hora = data.getHours().toString(); hora = (hora.length>1)? hora : "0"+hora;
    var minutos = data.getMinutes().toString(); minutos = (minutos.length>1)? minutos : "0"+minutos;
    if(comHorario){
        return ano+"-"+mes+"-"+dia + " " + hora+":"+minutos;
    }
    return ano+"-"+mes+"-"+dia;
}

/****** 
** Enable customization script to change agreement calculation. 
** Input: 
**	stateId -> Current state, whose agreement percentage is being calculated. 
**	agreementData.get("currentPercentage") -> Current percentage, calculated by the workflow engine
**	agreementData.get("currentDestState") -> Current destination state. Zero, if process won't move
**	agreementData.get("currentDestUsers") -> Current destination users. Empty if process won't move
**/
function calculateAgreement(currentState, agreementData) {
	var indAprov = hAPI.getChildrenIndexes("tblAprovadores"), totalAprov = 0, user = getValue("WKUser"), nextTask = getValue("WKNextState"), codProcess = hAPI.getCardValue("hd_solicitacao_numProcesso");
	var filtrosProtheus = [], strObs = '', strUserObs = '', aprovFeita = false, strAprovsPendentes = '';

	if(hAPI.getCardValue('hd_sc_encerradoProtheus') != 'true'){
		hAPI.setCardValue('hd_solicitacao_integraAlcadas', false);
		hAPI.setCardValue('hd_solicitacao_integraProdutos', false);
		hAPI.setCardValue('hd_solicitacao_pendenciaAprov', true);

		if(hAPI.getCardValue('hd_sc_encerradoProtheus') == 'edit'){
			hAPI.setCardValue('hd_solicitacao_integraAlcadas', true);
			aprovFeita = true;
		}
		
		filtrosProtheus.push(DatasetFactory.createConstraint("processTaskPK.processInstanceId", codProcess, codProcess, ConstraintType.MUST));
		var dtsRetorno = DatasetFactory.getDataset("processTask", null, filtrosProtheus, null);
		if(dtsRetorno.rowsCount > 0){
			var lastComment = dtsRetorno.rowsCount-1;
			strObs = dtsRetorno.getValue(lastComment, "taskObservation");
			strUserObs = dtsRetorno.getValue(lastComment, "processTaskPK.colleagueId");
		}

		var indChat = hAPI.getChildrenIndexes("tblChat");
		if(strObs == "" && indChat.length > 0){
			var lastMsg = indChat.length-1;

			strObs     = hAPI.getCardValue('hd_chat_observacao___' + indChat[lastMsg]);
			strUserObs = hAPI.getCardValue('hd_chat_idUsuario___' + indChat[lastMsg]);
		}

		for(var i=0; i < indAprov.length; i++){
			if(hAPI.getCardValue('hd_aprovador_codigoFluig___' + indAprov[i]) == user){
				aprovFeita = true;
				if(nextTask == 31){
					hAPI.setCardValue('hd_aprovador_statusAprovacao___' + indAprov[i], 'REPROVADO');
				}
				else{
					hAPI.setCardValue('hd_aprovador_statusAprovacao___' + indAprov[i], 'APROVADO');
				}

				if(user == strUserObs && strObs != ''){
					hAPI.setCardValue('hd_aprovacao_observacao___' + indAprov[i], strObs);
				}

				var aprovacoesFeitas = hAPI.getCardValue('hd_solicitacao_aprovsAtuados');
				if(aprovacoesFeitas != ''){
					aprovacoesFeitas += ',';
				}
				hAPI.setCardValue('hd_solicitacao_aprovsAtuados', aprovacoesFeitas + user);
			}
			
			if(hAPI.getCardValue('hd_aprovador_statusAprovacao___' + indAprov[i]) != ''){
				totalAprov++;
			}
			else{
				if(strAprovsPendentes != ''){
					strAprovsPendentes += ',';
				}
				strAprovsPendentes += hAPI.getCardValue('hd_aprovador_codigoFluig___' + indAprov[i]);
			}
		}

		hAPI.setCardValue('hd_aprovador_custo', strAprovsPendentes);

		if(totalAprov == indAprov.length && totalAprov > 0){
			hAPI.setCardValue('hd_solicitacao_pendenciaAprov', false);
		}

		if(/*totalAprov == indAprov.length && totalAprov > 0*/aprovFeita){
			agreementData.put("currentPercentage", 100);
			agreementData.put("currentDestState", 34);
			agreementData.put("currentDestUsers", 'System:Auto');
		}
	}
	else{
		hAPI.setCardValue('hd_solicitacao_integraAlcadas', true);
		hAPI.setCardValue('hd_solicitacao_integraProdutos', true);
		hAPI.setCardValue('hd_solicitacao_pendenciaAprov', false);

		agreementData.put("currentPercentage", 100);
		agreementData.put("currentDestState", 34);
		agreementData.put("currentDestUsers", 'System:Auto');
	}
}

function servicetask16(attempt, message) {
    if(hAPI.getCardValue('hd_solicitacao_integraAlcadas') != 'true'){
        atualizaProtheusAlcadas();
    }
    else{
        // D6: com integraAlcadas ja true o atualizaProtheusAlcadas nao roda, e e la dentro
        // que o log e limpo. Sem isto o txta_logIntegration guarda para sempre o erro da
        // ultima falha, e quem for diagnosticar depois le um erro ja resolvido como se
        // fosse a causa atual. Escolhi limpar em vez de datar cada entrada: o valor aqui
        // e o diagnostico do estado corrente, e o historico fica no log do servidor.
        hAPI.setCardValue('txta_logIntegration', "");
    }
}

/**
 * R2 - devolve o CR_STATUS quando a alcada JA esta processada no Protheus (03 ou 06),
 * ou string vazia em qualquer outro caso.
 *
 * Casa por CR_NUM + CR_FILIAL + CR_APROV. A filial e obrigatoria: o CR_NUM nao a
 * codifica, e a mesma medicao pode ter ...001 em duas filiais diferentes - marcar
 * pelo registro da filial errada aprovaria a alcada errada.
 *
 * Linha ausente da SCR devolve '' de proposito, ou seja, mantem a falha visivel.
 * Tratar ausencia como "ja processada" esconderia erro de chave - foi exatamente
 * uma mensagem "Registro nao Localizado" que mascarou por meses o numero de
 * documento errado. Medicao ja expurgada do Protheus fica presa e visivel, que e
 * o erro mais barato dos dois.
 */
function statusAlcadaProtheus(empresa, filial, numDoc, codAprov) {
    try {
        var medicao = (numDoc + '').substring(0, 6);

        var cMed = DatasetFactory.createConstraint("C_MEDICAO",   medicao,  medicao,  ConstraintType.MUST);
        var cEmp = DatasetFactory.createConstraint("CEMP",        empresa,  empresa,  ConstraintType.MUST);
        var cApr = DatasetFactory.createConstraint("C_APROVADOR", codAprov, codAprov, ConstraintType.MUST);

        var dts = DatasetFactory.getDataset("dts_getScrMedicao_stg", null, [cMed, cEmp, cApr], null);

        if (dts == null || dts.rowsCount == 0) { return ''; }

        var cols = dts.getColumnsName();
        if (cols.length == 1 && cols[0] == 'ERRO') { return ''; }

        for (var i = 0; i < dts.rowsCount; i++) {
            if (dts.getValue(i, 'CR_TIPO')   == 'IM' &&
                dts.getValue(i, 'CR_NUM')    == (numDoc + '') &&
                dts.getValue(i, 'CR_FILIAL') == (filial + '')) {

                var st = dts.getValue(i, 'CR_STATUS') + '';
                return (st == '03' || st == '06') ? st : '';
            }
        }
        return '';

    } catch (e) {
        log.info("statusAlcadaProtheus === " + e.toString());
        return '';
    }
}

/**
 * Explica em portugues uma falha de aprovacao causada pelo CONTRATO, ou devolve ''.
 *
 * Contrato cancelado depois da medicao faz o APROVCOM responder "EMPTYFORM - O
 * formulario Itens(GridDoc) nao foi preenchido", que nao menciona contrato nenhum.
 * Caso real: medicao 001485, contrato 000000000000121, filial 01 - revisao vigente
 * 002 com CN9_SITUAC '01' (Cancelado).
 *
 * So acrescenta informacao, nunca decide: falha na consulta devolve '' e o log fica
 * com a mensagem original do Protheus, como era antes.
 */
function diagnosticoContrato(empresa, filial, contrato) {
    try {
        if (contrato == '') { return ''; }

        var dts = DatasetFactory.getDataset("dts_getSituacaoContrato_stg", null, [
            DatasetFactory.createConstraint("C_CONTRATO", contrato, contrato, ConstraintType.MUST),
            DatasetFactory.createConstraint("C_FILIAL",   filial,   filial,   ConstraintType.MUST),
            DatasetFactory.createConstraint("CEMP",       empresa,  empresa,  ConstraintType.MUST)
        ], null);

        if (dts == null || dts.rowsCount == 0) { return ''; }
        var cols = dts.getColumnsName();
        if (cols.length == 1 && cols[0] == 'ERRO') { return ''; }

        var situac = dts.getValue(0, 'CN9_SITUAC') + '';
        if (situac == '05') { return ''; }

        return "ATENCAO: o contrato " + contrato + " (revisao " + dts.getValue(0, 'CN9_REVISA') +
               ") esta com situacao " + situac + " - " + dts.getValue(0, 'SITUACAO_DESCR') +
               " no Protheus. O Protheus so aprova medicao de contrato Vigente (05), entao " +
               "esta aprovacao vai falhar ate o contrato ser reativado ou a medicao ser " +
               "estornada no Protheus. Tentar de novo pelo Fluig nao resolve.\n" +
               "Mensagem original do Protheus:";
    } catch (e) {
        log.info("diagnosticoContrato === " + e.toString());
        return '';
    }
}

/** Grava a decisao em todas as linhas de alcada do card que formam uma linha da SCR. */
function marcaDecisao(indices, decisao) {
    for (var i = 0; i < indices.length; i++) {
        hAPI.setCardValue('hd_alcada_descisao___' + indices[i], decisao);
    }
}

/**
 * Soma os valores de alcada de um grupo, no formato que o card ja usa ("10949.59",
 * "13000"). Um valor so volta intocado - e o caso comum, e nao muda nada do que ja
 * funcionava. A soma e feita em centavos para 10904.07 + 45.52 nao virar 10949.590000001.
 */
function somaValores(valores) {
    if (valores.length == 1) { return valores[0]; }
    var centavos = 0;
    for (var i = 0; i < valores.length; i++) {
        var n = parseFloat((valores[i] + '').replace(',', '.'));
        if (!isNaN(n)) { centavos += Math.round(n * 100); }
    }
    return String(centavos / 100);
}

/**
 * CR_TOTAL da linha da SCR, quando ele so difere da soma do card por arredondamento.
 *
 * Tolerancia de 1 centavo por item somado: cada item vem arredondado em 2 casas, entao
 * o erro acumulado nao passa disso. Diferenca maior NAO e arredondamento - e alcada que
 * mudou -, e ai o valor do card e mantido de proposito: a chamada falha visivel, em vez
 * de aprovar no Protheus um valor que o aprovador nao viu no Fluig.
 *
 * Qualquer falha na consulta devolve a soma do card, ou seja, o comportamento de antes.
 */
function totalDaScr(empresa, filial, numDoc, codAprov, somaCard, qtdItens) {
    try {
        var medicao = (numDoc + '').substring(0, 6);
        var dts = DatasetFactory.getDataset("dts_getScrMedicao_stg", null, [
            DatasetFactory.createConstraint("C_MEDICAO",   medicao,  medicao,  ConstraintType.MUST),
            DatasetFactory.createConstraint("CEMP",        empresa,  empresa,  ConstraintType.MUST),
            DatasetFactory.createConstraint("C_APROVADOR", codAprov, codAprov, ConstraintType.MUST),
            DatasetFactory.createConstraint("C_TIPO",      "IM",     "IM",     ConstraintType.MUST),
            // C_COM_TOTAL, e nao C_CAMPOS: C_CAMPOS faz o dataset voltar sem estrutura, e
            // foi por isso que a primeira versao desta funcao nunca corrigiu nada.
            DatasetFactory.createConstraint("C_COM_TOTAL", "S",      "S",      ConstraintType.MUST)
        ], null);

        if (dts == null || dts.rowsCount == 0) { return somaCard; }
        var cols = dts.getColumnsName();
        if (cols.length == 1 && cols[0] == 'ERRO') { return somaCard; }

        for (var i = 0; i < dts.rowsCount; i++) {
            if (dts.getValue(i, 'CR_NUM') == (numDoc + '') && dts.getValue(i, 'CR_FILIAL') == (filial + '')) {
                var total = parseFloat((dts.getValue(i, 'CR_TOTAL') + '').replace(',', '.'));
                var soma  = parseFloat((somaCard + '').replace(',', '.'));
                if (isNaN(total) || isNaN(soma)) { return somaCard; }

                var difCentavos = Math.abs(Math.round(total * 100) - Math.round(soma * 100));
                if (difCentavos == 0) { return somaCard; }
                if (difCentavos <= qtdItens) {
                    log.info("totalDaScr - " + numDoc + ": soma do card " + somaCard +
                             ", CR_TOTAL " + total + " - enviando o CR_TOTAL (arredondamento)");
                    return String(Math.round(total * 100) / 100);
                }
                return somaCard;
            }
        }
        return somaCard;
    } catch (e) {
        log.info("totalDaScr === " + e.toString());
        return somaCard;
    }
}

var indexActualAprov = '';
function atualizaProtheusAlcadas() {
    try {
        var filial      = hAPI.getCardValue('hd_solicitacao_nroFilial').trim();
        var empresa     = hAPI.getCardValue('hd_solicitacao_codFilial').trim();
        var codProtheus = hAPI.getCardValue('hd_medicao_numero').trim()/* + hAPI.getCardValue('hd_planilha_numero').trim()*/;
        var indAprov    = hAPI.getChildrenIndexes("tblAprovadores");
        var indAlcadas  = hAPI.getChildrenIndexes("tblAlcadas");

        var codAprov = '', valorAprov = '', obsAprov = '';
        for (var y = 0; y < indAprov.length; y++) {
            if(hAPI.getCardValue('hd_aprovacao_efetivada___' + indAprov[y]) != 'true' && hAPI.getCardValue('hd_aprovador_statusAprovacao___' + indAprov[y]) != ''){
                codAprov   = hAPI.getCardValue('hd_aprovador_codigo___' + indAprov[y]);
                if(hAPI.getCardValue('hd_aprovador_statusAprovacao___' + indAprov[y]) == "APROVADO"){
                    valorAprov = "001"
                }
                else if(hAPI.getCardValue('hd_aprovador_statusAprovacao___' + indAprov[y]) == "REPROVADO"){
                    valorAprov = "005"
                }
                obsAprov = hAPI.getCardValue('hd_aprovacao_observacao___' + indAprov[y]);

                // O Protheus exige CR_OBS preenchido na reprovacao (operacao 005) e recusa a
                // chamada com "O campo Observacoes (CR_OBS) nao foi preenchido". O Fluig permite
                // reprovar sem comentario, entao sem este texto a solicitacao trava em Tratar falhas.
                if(obsAprov == '' && valorAprov == "005"){
                    obsAprov = "Reprovado no Fluig sem justificativa informada pelo aprovador "
                             + hAPI.getCardValue('hd_aprovador_nome___' + indAprov[y]);
                }

                indexActualAprov = indAprov[y];
            }
        }

        /*var cEmp    = DatasetFactory.createConstraint('C_EMPRESA',       empresa,     empresa , ConstraintType.MUST);
        var cFilial = DatasetFactory.createConstraint('C_FILIAL',        filial,      filial , ConstraintType.MUST);
        var cNum    = DatasetFactory.createConstraint('C_NUMERO_DOC',    codProtheus, codProtheus  , ConstraintType.MUST);
        var cTipo   = DatasetFactory.createConstraint('C_TIPO_DOC',      "IM",        "IM"   , ConstraintType.MUST);
        var cAprov  = DatasetFactory.createConstraint('C_APROVADOR_COD', codAprov,    codAprov, ConstraintType.MUST);
        var cOpc    = DatasetFactory.createConstraint('C_OPERACAO',      valorAprov,  valorAprov, ConstraintType.MUST);
        var cObs    = DatasetFactory.createConstraint('C_OBSERVACAO',    obsAprov,    obsAprov, ConstraintType.MUST);
        var dts     = DatasetFactory.getDataset('dts_setAprovacaoComprasProtheus_jynx', null, [cEmp, cFilial, cNum, cTipo, cAprov, cOpc, cObs], null);

        log.info("Aprovação IM ===")
        log.dir(dts)
        if(dts.rowsCount > 0 && dts.getValue(0, "STATUS") == "SUCESSO"){
            hAPI.setCardValue('hd_solicitacao_integraAlcadas', true);
            hAPI.setCardValue('hd_aprovacao_efetivada___' + indexActualAprov, true);
        }
        else{
            var c1 = DatasetFactory.createConstraint("C_NUMSOLIC", codProtheus, codProtheus, ConstraintType.MUST);
            var c2 = DatasetFactory.createConstraint("CEMP", empresa, empresa, ConstraintType.MUST);
            var c3 = DatasetFactory.createConstraint("C_STATUS_ALCADA_ARR", "'03','06'", "'03','06'", ConstraintType.MUST);
            var c4 = DatasetFactory.createConstraint("C_FILIAL", filial, filial, ConstraintType.MUST);
            var c5 = DatasetFactory.createConstraint("C_APROVADOR", codAprov, codAprov, ConstraintType.MUST);
            var dtsRetorno = DatasetFactory.getDataset("dts_getMedicoesContratosAprovProtheus_jynx", null, [c1, c2, c3, c4, c5], null);

            if(dtsRetorno.rowsCount > 0 && dtsRetorno.getValue(0, "MEDICAO_NUMERO") == (codProtheus + "") && dtsRetorno.getValue(0, "FILIAL_CODIGO") == (filial + "")){
                hAPI.setCardValue('hd_solicitacao_integraAlcadas', true);
                hAPI.setCardValue('hd_aprovacao_efetivada___' + indexActualAprov, true);
            }
            else if(dts.rowsCount > 0 && dts.getValue(0, "STATUS") == "ERRO"){
                hAPI.setCardValue('txta_logIntegration', dts.getValue(0, "MENSAGEM") + "");
            }
        }*/

        hAPI.setCardValue('txta_logIntegration', "");
        var totalPendentes = 0, totalAlcadas = 0;

        // O card guarda a alcada POR ITEM (DBM, uma linha por DBM_ITEM), mas o APROVCOM
        // casa com a SCR, que tem UMA linha por documento + aprovador, com o total. Quando
        // dois itens caem no mesmo sequencial, o card tem duas linhas com o mesmo CR_NUM, e
        // mandar uma chamada por linha manda o valor partido - nenhum casa com o CR_TOTAL e
        // o Protheus responde "Registro nao Localizado". Caso real: medicao 002027, filial
        // 12, CR_NUM 002027000001001 com CR_TOTAL 10949.59, card com 10904.07 + 45.52.
        //
        // Por isso as linhas sao agrupadas por numero do documento (o aprovador ja e um so
        // aqui) e cada grupo vira UMA chamada, com a soma do grupo inteiro - inclusive de
        // linhas ja decididas, porque o CR_TOTAL e do documento todo. Grupo de uma linha so,
        // que e o caso comum (002087: cada rateio com seu sequencial), manda o valor exatamente
        // como estava no card.
        var grupos = [], porDoc = {};
        for (var z = 0; z < indAlcadas.length; z++) {
            if(codAprov != hAPI.getCardValue('hd_alcada_codAprovador___' + indAlcadas[z])){ continue; }
            totalAlcadas++;

            var codDocLinha = hAPI.getCardValue('hd_alcada_numDocumento___' + indAlcadas[z]);
            var g = porDoc[codDocLinha];
            if(g == null){
                g = { codDoc: codDocLinha, indices: [], valores: [], pendente: false };
                porDoc[codDocLinha] = g;
                grupos.push(g);
            }
            g.indices.push(indAlcadas[z]);
            g.valores.push(hAPI.getCardValue('hd_alcada_valorItem___' + indAlcadas[z]) + '');
            if(hAPI.getCardValue('hd_alcada_descisao___' + indAlcadas[z]) == ""){ g.pendente = true; }
        }

        for (var k = 0; k < grupos.length; k++) {
            var grupo = grupos[k];
            if(!grupo.pendente){ continue; }

            var codDoc = grupo.codDoc;
            var valor  = somaValores(grupo.valores);

            // Soma de itens arredondados pode diferir do CR_TOTAL em centavos - a SCR soma
            // com precisao cheia e so arredonda no fim. 1 centavo basta para o APROVCOM
            // responder "Registro nao Localizado". Caso real: medicao 016663, empresa 06,
            // CR_NUM ...001 com CR_TOTAL 169559.44 e soma do card 169559.43.
            if(grupo.valores.length > 1){
                valor = totalDaScr(empresa, filial, codDoc, codAprov, valor, grupo.valores.length);
            }

            var cEmp    = DatasetFactory.createConstraint('C_EMPRESA',       empresa,     empresa , ConstraintType.MUST);
            var cFilial = DatasetFactory.createConstraint('C_FILIAL',        filial,      filial , ConstraintType.MUST);
            var cNum    = DatasetFactory.createConstraint('C_NUMERO_DOC',    codDoc,      codDoc  , ConstraintType.MUST);
            var cTipo   = DatasetFactory.createConstraint('C_TIPO_DOC',      "IM",        "IM"   , ConstraintType.MUST);
            var cAprov  = DatasetFactory.createConstraint('C_APROVADOR_COD', codAprov,    codAprov, ConstraintType.MUST);
            var cOpc    = DatasetFactory.createConstraint('C_OPERACAO',      valorAprov,  valorAprov, ConstraintType.MUST);
            var cObs    = DatasetFactory.createConstraint('C_OBSERVACAO',    obsAprov,    obsAprov, ConstraintType.MUST);
            var cValor  = DatasetFactory.createConstraint('C_VALOR_TOTAL',   valor,       valor, ConstraintType.MUST);
            var dts     = DatasetFactory.getDataset('dts_setAprovacaoComprasProtheus_jynx', null, [cEmp, cFilial, cNum, cTipo, cAprov, cOpc, cObs, cValor], null);

            if(dts.rowsCount > 0 && dts.getValue(0, "STATUS") == "SUCESSO"){
                marcaDecisao(grupo.indices, valorAprov);
            }
            else{
                // R2: a chamada pode ter falhado porque a alcada ja foi aprovada direto
                // no Protheus. Nesse caso a API responde "Registro nao Localizado" e,
                // sem esta verificacao, a solicitacao trava em Tratar falhas para sempre:
                // a decisao so e gravada por uma chamada bem-sucedida, que nunca mais
                // vai acontecer porque o trabalho ja foi feito la.
                var statusScr = statusAlcadaProtheus(empresa, filial, codDoc, codAprov);

                if(statusScr != ''){
                    marcaDecisao(grupo.indices, valorAprov);
                    var msgOk = hAPI.getCardValue('txta_logIntegration');
                    hAPI.setCardValue('txta_logIntegration', msgOk + "\nAlcada " + codDoc +
                        " ja processada no Protheus (CR_STATUS " + statusScr +
                        ") - decisao " + valorAprov + " marcada sem nova chamada.");
                }
                else{
                    totalPendentes++;
                    var msgAtual = hAPI.getCardValue('txta_logIntegration');

                    // Uma vez por execucao, e no topo do log: e a explicacao que o
                    // Protheus nao da. Com o contrato fora de vigencia toda linha
                    // falha pelo mesmo motivo, entao repetir por linha so poluiria.
                    if(totalPendentes == 1){
                        var aviso = diagnosticoContrato(empresa, filial,
                                        hAPI.getCardValue('hd_contrato_numero').trim());
                        if(aviso != ''){ msgAtual = aviso + "\n" + msgAtual; }
                    }

                    hAPI.setCardValue('txta_logIntegration', msgAtual + "\n" + dts.getValue(0, "MENSAGEM"));
                }
            }
        }

        if(totalPendentes == 0 && totalAlcadas > 0){
            hAPI.setCardValue('hd_solicitacao_integraAlcadas', true);
            hAPI.setCardValue('hd_aprovacao_efetivada___' + indexActualAprov, true);
        }
    } catch (e) {
        log.info("Erro serviceTask16 === " + e.toString())
    }
}

/**
 * Confere aprovacao no Protheus - roda depois da integracao (servicetask16) ter dado certo.
 *
 * O APROVCOM responde "Registro Aprovado com Sucesso!" e as vezes nao grava nada na SCR.
 * Casos reais: medicoes 002474, 002173, 002207 e 002258 (solicitacao 5401, que o Fluig
 * deu como aprovada em 23/10/2026 com a alcada do David ainda em CR_STATUS 02).
 *
 * Por isso, as alcadas com decisao marcada do aprovador que acabou de agir sao conferidas
 * na SCR (ver aprovadorDaRodada):
 *   - decisao 001 (aprovar) precisa estar em 03; 005 (reprovar) precisa estar em 06.
 *   - tudo conferido: hd_conferencia_status = OK e o fluxo segue.
 *   - alguma divergente: a decisao dela e desmarcada, para o servicetask16 mandar de novo,
 *     e o resultado e REENVIAR. Depois de MAX_REENVIOS reenvios sem gravar, e FALHA e a
 *     solicitacao vai para Tratar falhas com o motivo no txta_logIntegration.
 *
 * Diferente do alcadaSeguePendente da v13, aqui consulta que falha conta como NAO
 * conferida: com os reenvios, uma queda rapida do restqry e absorvida, e o Fluig nunca
 * encerra uma solicitacao sem ver a SCR.
 */
var MAX_REENVIOS = 3;

function servicetask40(attempt, message) {
	try {
		// Encerrada ou editada no Protheus: o calculateAgreement ja decidiu sem chamar o
		// APROVCOM, e a SCR pode ter sido refeita. Nao ha o que conferir.
		var encerrado = hAPI.getCardValue("hd_sc_encerradoProtheus");
		if (encerrado == "true" || encerrado == "edit") {
			conferenciaOk();
			return;
		}

		var divergentes = alcadasNaoGravadas();
		if (divergentes.length == 0) {
			conferenciaOk();
			return;
		}

		var reenvios = parseInt(hAPI.getCardValue("hd_conferencia_reenvios"), 10);
		if (isNaN(reenvios)) {
			reenvios = 0;
		}

		var detalhe = "";
		for (var i = 0; i < divergentes.length; i++) {
			detalhe +=
				"\nAlcada " +
				divergentes[i].codDoc +
				" (aprovador " +
				divergentes[i].codAprov +
				"): " +
				divergentes[i].motivo;
		}

		if (reenvios < MAX_REENVIOS) {
			desmarcaDecisoes(divergentes);
			hAPI.setCardValue("hd_conferencia_reenvios", String(reenvios + 1));
			hAPI.setCardValue("hd_conferencia_status", "REENVIAR");
			log.info(
				"servicetask40 - solicitacao " +
					getValue("WKNumProces") +
					": reenvio " +
					(reenvios + 1) +
					" de " +
					MAX_REENVIOS +
					detalhe
			);
			return;
		}

		// Volta para o servicetask16 a partir de Tratar falhas com a decisao desmarcada e o
		// contador zerado, ou seja, com mais MAX_REENVIOS tentativas.
		desmarcaDecisoes(divergentes);
		hAPI.setCardValue("hd_conferencia_reenvios", "0");
		hAPI.setCardValue("hd_conferencia_status", "FALHA");
		hAPI.setCardValue(
			"txta_logIntegration",
			"O Protheus respondeu sucesso, mas a aprovacao nao foi gravada na SCR depois de " +
				MAX_REENVIOS +
				" reenvios. A solicitacao nao foi encerrada para a medicao nao ficar aprovada " +
				"no Fluig e pendente no Protheus. Verificar no Protheus." +
				detalhe
		);
	} catch (e) {
		// Erro inesperado nao pode encerrar a solicitacao: vai para Tratar falhas.
		log.info("Erro servicetask40 === " + e.toString());
		hAPI.setCardValue("hd_conferencia_status", "FALHA");
		hAPI.setCardValue("txta_logIntegration", "Erro ao conferir a aprovacao no Protheus: " + e.toString());
	}
}

function conferenciaOk() {
	hAPI.setCardValue("hd_conferencia_reenvios", "0");
	hAPI.setCardValue("hd_conferencia_status", "OK");
}

/**
 * Alcadas do card com decisao marcada que a SCR nao confirma, agrupadas por documento +
 * aprovador (o card guarda uma linha por item; a SCR, uma por documento - ver servicetask16).
 */
function alcadasNaoGravadas() {
	var empresa = hAPI.getCardValue("hd_solicitacao_codFilial").trim();
	var filial = hAPI.getCardValue("hd_solicitacao_nroFilial").trim();
	var medicao = hAPI.getCardValue("hd_medicao_numero").trim();
	var indAlcadas = hAPI.getChildrenIndexes("tblAlcadas");
	var aprovador = aprovadorDaRodada();

	var grupos = [],
		porChave = {};
	for (var i = 0; i < indAlcadas.length; i++) {
		var decisao = hAPI.getCardValue("hd_alcada_descisao___" + indAlcadas[i]);
		if (decisao == "") {
			continue;
		}
		var codDoc = hAPI.getCardValue("hd_alcada_numDocumento___" + indAlcadas[i]);
		var codAprov = hAPI.getCardValue("hd_alcada_codAprovador___" + indAlcadas[i]);
		if (aprovador != "" && codAprov != aprovador) {
			continue;
		}
		var chave = codDoc + "|" + codAprov;
		var g = porChave[chave];
		if (g == null) {
			g = { codDoc: codDoc, codAprov: codAprov, decisao: decisao, indices: [], motivo: "" };
			porChave[chave] = g;
			grupos.push(g);
		}
		g.indices.push(indAlcadas[i]);
	}

	if (grupos.length == 0) {
		return [];
	}

	var scr = statusScr(empresa, filial, medicao);
	var divergentes = [];
	for (var k = 0; k < grupos.length; k++) {
		var grupo = grupos[k];
		var esperado = grupo.decisao == "005" ? "06" : "03";

		if (scr == null) {
			grupo.motivo = "nao foi possivel consultar a SCR";
		} else if (scr[grupo.codDoc + "|" + grupo.codAprov] == null) {
			grupo.motivo = "linha nao encontrada na SCR da filial " + filial;
		} else if (scr[grupo.codDoc + "|" + grupo.codAprov] != esperado) {
			grupo.motivo =
				"CR_STATUS " +
				scr[grupo.codDoc + "|" + grupo.codAprov] +
				", esperado " +
				esperado +
				" (decisao " +
				grupo.decisao +
				")";
		} else {
			continue;
		}
		divergentes.push(grupo);
	}
	return divergentes;
}

/**
 * Codigo Protheus do aprovador que acabou de agir: o ultimo login de
 * hd_solicitacao_aprovsAtuados (o calculateAgreement acrescenta um a cada aprovacao).
 *
 * So ele e conferido porque o servicetask16 reenvia um aprovador por vez - o ultimo da
 * tabela ainda nao efetivado. Desmarcar tambem a decisao de um aprovador anterior a
 * deixaria desmarcada para sempre, sem reenvio. Sem aprovador identificado, devolve '' e
 * todas as decisoes marcadas sao conferidas.
 */
function aprovadorDaRodada() {
	var atuados = hAPI.getCardValue("hd_solicitacao_aprovsAtuados").split(",");
	var login = atuados[atuados.length - 1].trim();
	if (login == "") {
		return "";
	}
	var indAprov = hAPI.getChildrenIndexes("tblAprovadores");
	for (var y = 0; y < indAprov.length; y++) {
		if (hAPI.getCardValue("hd_aprovador_codigoFluig___" + indAprov[y]) == login) {
			return hAPI.getCardValue("hd_aprovador_codigo___" + indAprov[y]);
		}
	}
	return "";
}

/**
 * CR_STATUS da SCR da medicao na filial do card, por "CR_NUM|CR_APROV", ou null se a
 * consulta falhar. Casa pela filial porque o mesmo numero de medicao existe em filiais
 * diferentes (002258 tem linhas na 01 e na 12).
 */
function statusScr(empresa, filial, medicao) {
	try {
		var dts = DatasetFactory.getDataset(
			"dts_getScrMedicao_stg",
			null,
			[
				DatasetFactory.createConstraint("C_MEDICAO", medicao, medicao, ConstraintType.MUST),
				DatasetFactory.createConstraint("CEMP", empresa, empresa, ConstraintType.MUST),
				DatasetFactory.createConstraint("C_TIPO", "IM", "IM", ConstraintType.MUST)
			],
			null
		);

		if (dts == null) {
			return null;
		}
		var cols = dts.getColumnsName();
		if (cols.length == 1 && cols[0] == "ERRO") {
			return null;
		}

		var mapa = {};
		for (var i = 0; i < dts.rowsCount; i++) {
			if (dts.getValue(i, "CR_FILIAL") + "" == filial) {
				mapa[dts.getValue(i, "CR_NUM") + "|" + dts.getValue(i, "CR_APROV")] = dts.getValue(i, "CR_STATUS") + "";
			}
		}
		return mapa;
	} catch (e) {
		log.info("statusScr servicetask40 === " + e.toString());
		return null;
	}
}

/**
 * Desfaz no card o que o servicetask16 marcou para as alcadas divergentes: a decisao da
 * alcada e o "efetivada" do aprovador. Sem isso o servicetask16 acha que nao ha nada a
 * enviar. integraAlcadas volta a false porque e o que faz o servicetask16 rodar de novo.
 */
function desmarcaDecisoes(divergentes) {
	var indAprov = hAPI.getChildrenIndexes("tblAprovadores");
	for (var i = 0; i < divergentes.length; i++) {
		for (var j = 0; j < divergentes[i].indices.length; j++) {
			hAPI.setCardValue("hd_alcada_descisao___" + divergentes[i].indices[j], "");
		}
		for (var y = 0; y < indAprov.length; y++) {
			if (hAPI.getCardValue("hd_aprovador_codigo___" + indAprov[y]) == divergentes[i].codAprov) {
				hAPI.setCardValue("hd_aprovacao_efetivada___" + indAprov[y], "false");
			}
		}
	}
	hAPI.setCardValue("hd_solicitacao_integraAlcadas", "false");
}
